package ai.pixelmind

import ai.pixelmind.engine.ClipTokenizer
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The tokenizer against a reference vector taken from the real CLIP vocabulary.
 *
 * `clip_reference.json` is generated by an independent implementation of the canonical CLIP BPE
 * over `openai/clip-vit-large-patch14`'s `vocab.json` and `merges.txt`, and carries the token ids
 * the reference produces for each prompt. Only the vocabulary entries and merge ranks those
 * prompts can reach are in the file — every rank is the true rank from `merges.txt`, so the
 * subset encodes them exactly as the full 49k-entry vocabulary does.
 *
 * This is the check the older tests could not make: they used a hand-built eight-token
 * vocabulary, which proves the framing and the padding but not that the port agrees with CLIP on
 * a real prompt. A tokenizer that is one merge off still produces 77 plausible ids, and the only
 * symptom is that the model ignores half the prompt.
 */
class ClipTokenizerReferenceTest {

    private data class Fixture(
        val tokenizer: ClipTokenizer,
        val cases: List<Pair<String, List<Long>>>
    )

    private fun fixture(): Fixture {
        val stream = javaClass.classLoader!!.getResourceAsStream("clip_reference.json")
            ?: error("clip_reference.json is missing from the test resources")
        val json = JSONObject(stream.bufferedReader().use { it.readText() })

        val vocabJson = json.getJSONObject("vocab")
        val encoder = HashMap<String, Int>(vocabJson.length())
        vocabJson.keys().forEach { encoder[it] = vocabJson.getInt(it) }

        val mergesJson = json.getJSONArray("merges")
        val ranks = HashMap<String, Int>(mergesJson.length())
        for (i in 0 until mergesJson.length()) {
            val pair = mergesJson.getJSONArray(i)
            // The rank table is keyed "left\u0000right", exactly as ClipTokenizer builds it.
            ranks[pair.getString(0) + '\u0000' + pair.getString(1)] = i
        }

        val casesJson = json.getJSONArray("cases")
        val cases = List(casesJson.length()) { i ->
            val case = casesJson.getJSONObject(i)
            val ids = case.getJSONArray("ids")
            case.getString("prompt") to List(ids.length()) { ids.getLong(it) }
        }
        return Fixture(
            ClipTokenizer(encoder, ranks, maxLength = json.getInt("maxLength")),
            cases
        )
    }

    @Test
    fun `every reference prompt encodes to the reference ids`() {
        val (tokenizer, cases) = fixture()
        assertTrue("the fixture carries no cases", cases.isNotEmpty())
        for ((prompt, expected) in cases) {
            assertEquals(
                "ids for prompt \"$prompt\"",
                expected,
                tokenizer.encode(prompt).toList()
            )
        }
    }

    @Test
    fun `the reference vector includes a prompt whose words need real merges`() {
        // Guards the fixture itself: if it were reduced to single characters, the test above
        // would pass while proving nothing about BPE.
        val (tokenizer, _) = fixture()
        val tokens = tokenizer.tokenize("mountain lake at sunrise")
        assertTrue("expected merged tokens, got $tokens", tokens.any { it.length > 2 })
        assertEquals(listOf("mountain</w>", "lake</w>", "at</w>", "sunrise</w>"), tokens)
    }

    @Test
    fun `the conditional text of a style preset still fits the 77-token window`() {
        // The style suffix is appended to every prompt, so a suffix that overflows the window
        // would silently truncate the user's own words out of the conditioning.
        val (tokenizer, _) = fixture()
        val ids = tokenizer.encode("a photo of a cat, photorealistic, ultra detailed")
        assertEquals(77, ids.size)
        assertEquals(49406L, ids[0])
        assertTrue("the trailing slots must be padding", ids.drop(20).all { it == 49407L })
    }
}
